{
  "root_cause": "The modal's click listener uses event.target.closest to detect elements with the close trigger attribute. Because the overlay has data-micromodal-close, any click inside the modal (including on a checkbox) bubbles up to the overlay, causing the modal to close and preventing the checkbox's default toggle action.",
  "repair_strategy": "Replace .closest with .matches in the onClick handler so that only clicks directly on elements bearing the close trigger attribute (the overlay itself or the close button) close the modal, allowing internal interactions like checkbox toggling to proceed normally.",
  "edits": [
    {
      "path": "lib/src/index.js",
      "sha256": "0db2038c36c8c8c4730018c0ea419249e45923efa8315729f12b4d8da0d5fa2c",
      "before": "    onClick (event) {
      if (event.target.closest(`[${ this.config.closeTrigger }]`)) {
        event.preventDefault()
        event.stopPropagation()
        this.closeModal(event)
      }
    }",
      "after": "    onClick (event) {
      if (event.target.matches(`[${ this.config.closeTrigger }]`)) {
        event.preventDefault()
        event.stopPropagation()
        this.closeModal(event)
      }
    }"
  }
}
